/**
 * Builds and owns the three stores behind {@link ThreeTierParityCorpus}, one per {@link Dataset}.
 *
 * <p>
 * Each dataset uses the same store configuration as the benchmark its cells were taken from, so the parity numbers stay
 * comparable with the historical runs of {@link FoafCliqueQueryBenchmark}, {@link CorrelatedBenchmark} and
 * {@link ThemeQueryBenchmark}; the only configuration difference between regimes is the direct-adjacency mode.
 *
 * <p>
 * Fixtures are cached per JVM and per dataset, because JMH creates a fresh {@code @State} instance for every benchmark
 * method: without the cache, a full sweep run with {@code --forks 0} would regenerate the FOAF store once per cell.
 * With the cache, one JVM invocation builds each dataset it touches exactly once. Forked runs get one JVM per cell
 * anyway, so the cache is simply inert there.
 *
 * <p>
 * The cache is keyed by dataset only, not by regime: {@link ThreeTierRegime#pin(ThreeTierRegime)} already guarantees
 * one regime per JVM, and {@link #fixture} pins before opening anything, so a mismatched second regime fails loudly
 * instead of silently reusing a store built under different switches. The engagement census, which must visit all three
 * regimes, uses {@link #openIsolated} instead and closes each store before moving on.
 */
final class ThreeTierParityFixtures {

	/** Where {@link ThemeQueryBenchmark} keeps its shared, {@code mvn clean}-protected multi-theme store. */
	private static final String THEME_STORE_PATH = "core/sail/lmdb/target/lmdb-theme-query-benchmark/complete";
	private static final String THEME_STORE_PATH_IN_MODULE = "target/lmdb-theme-query-benchmark/complete";
	private static final String THEME_EXPECTED_SIZES_FILE = "expected-db-file-sizes.properties";
	private static final String THEME_TRIPLES_DATA_FILE = "triples/data.mdb";
	private static final String THEME_VALUES_DATA_FILE = "values/data.mdb";
	private static final String THEME_TRIPLE_INDEXES_PROPERTY = "triple.indexes";
	private static final String THEME_TRIPLES_SIZE_PROPERTY = "triples.data.mdb.size.bytes";
	private static final String THEME_VALUES_SIZE_PROPERTY = "values.data.mdb.size.bytes";

	static final String ADJACENCY_TIMEOUT_SECONDS_PROPERTY = "rdf4j.lmdb.threeTierParity.adjacencyTimeoutSeconds";
	static final String COMPILE_TIMEOUT_SECONDS_PROPERTY = "rdf4j.lmdb.threeTierParity.compileTimeoutSeconds";
	/**
	 * Number of people in the generated FOAF store. The benchmark default of 5000 matches
	 * {@link FoafCliqueQueryBenchmark} so the scores are comparable; the engagement census lowers it, because it only
	 * needs each shape to execute and engage, not to be slow.
	 */
	static final String FOAF_PEOPLE_PROPERTY = "rdf4j.lmdb.threeTierParity.foafPeople";
	/**
	 * Outer rows in the generated correlated store; the benchmark default of 1000 matches {@link CorrelatedBenchmark}.
	 */
	static final String CORRELATED_OUTER_ROWS_PROPERTY = "rdf4j.lmdb.threeTierParity.correlatedOuterRows";
	private static final long DEFAULT_ADJACENCY_TIMEOUT_SECONDS = 900L;
	private static final long DEFAULT_COMPILE_TIMEOUT_SECONDS = 120L;

	private static final Map<Dataset, Fixture> FIXTURES = new EnumMap<>(Dataset.class);
	private static boolean cleanupHookInstalled;

	private ThreeTierParityFixtures() {
	}

	/**
	 * Returns the cached fixture for one dataset under one regime, building it on first use, and pins the JVM to the
	 * regime so a second differing regime throws rather than mixing measurements.
	 */
	static synchronized Fixture fixture(Dataset dataset, ThreeTierRegime regime) {
		ThreeTierRegime.pin(regime);
		installCleanupHook();
		Fixture cached = FIXTURES.get(dataset);
		if (cached != null) {
			return cached;
		}
		Fixture fixture = openIsolated(dataset, regime);
		FIXTURES.put(dataset, fixture);
		return fixture;
	}

	/**
	 * Deletes the generated stores when the JVM exits. The fixtures are deliberately JVM-scoped rather than
	 * trial-scoped (see the class comment), so no {@code @TearDown} can own their lifetime — and JMH forks one JVM per
	 * benchmark cell, so without this a full sweep strands one multi-megabyte LMDB directory per cell in the system
	 * temp directory.
	 */
	private static void installCleanupHook() {
		if (cleanupHookInstalled) {
			return;
		}
		cleanupHookInstalled = true;
		Runtime.getRuntime()
				.addShutdownHook(new Thread(ThreeTierParityFixtures::closeAll, "three-tier-parity-cleanup"));
	}

	/**
	 * Opens a fresh, uncached fixture without pinning the JVM. The caller owns it and must {@link Fixture#close()} it.
	 * Only the engagement census uses this, because it deliberately visits all three regimes in one JVM: it asserts
	 * engagement witnesses and cross-regime row-count parity rather than timings, so carry-over between regimes cannot
	 * corrupt its verdict as long as each store is closed before the next opens.
	 */
	static Fixture openIsolated(Dataset dataset, ThreeTierRegime regime) {
		regime.applyProperties();
		return switch (dataset) {
		case FOAF -> openFoaf(regime);
		case CORRELATED -> openCorrelated(regime);
		case THEME -> openTheme(regime);
		};
	}

	/**
	 * Closes and (for generated datasets) deletes every cached fixture built in this JVM. Tolerates a failure on one
	 * fixture so the others are still released — this runs from a shutdown hook, where giving up early means leaking.
	 */
	static synchronized void closeAll() {
		for (Fixture fixture : FIXTURES.values()) {
			try {
				fixture.close();
			} catch (RuntimeException e) {
				System.err.println("Failed to release the " + fixture.dataset + " fixture: " + e);
			}
		}
		FIXTURES.clear();
	}

	private static Fixture openFoaf(ThreeTierRegime regime) {
		int people = Integer.getInteger(FOAF_PEOPLE_PROPERTY, 5000);
		// The clique share, sizes and random-edge count scale with the population so a reduced-scale run keeps the same
		// shape mix (cliques to intersect, long-range edges to gallop over) as the 5000-person benchmark scale.
		int randomEdges = people * 3;
		File dataDir = temporaryDirectory("rdf4j-lmdb-three-tier-foaf");
		Fixture fixture = open(Dataset.FOAF, regime,
				regime.applyTo(FoafCliqueQueryBenchmark.createBenchmarkConfig()), dataDir, dataDir);
		try (SailRepositoryConnection connection = fixture.repository.getConnection()) {
			new FoafCliqueDataGenerator(people, 30, 3, 8, randomEdges, 12345L).populate(connection);
			populateChainShapes(connection, people);
		}
		fixture.awaitAdjacency();
		return fixture;
	}

	private static Fixture openCorrelated(ThreeTierRegime regime) {
		int outerRows = Integer.getInteger(CORRELATED_OUTER_ROWS_PROPERTY, CorrelatedData.OUTER_ROWS);
		File dataDir = temporaryDirectory("rdf4j-lmdb-three-tier-correlated");
		Fixture fixture = open(Dataset.CORRELATED, regime,
				regime.applyTo(new LmdbStoreConfig("spoc,posc,ospc")), dataDir, dataDir);
		try (SailRepositoryConnection connection = fixture.repository.getConnection()) {
			populateCorrelated(connection, outerRows);
		}
		fixture.awaitAdjacency();
		return fixture;
	}

	private static Fixture openTheme(ThreeTierRegime regime) {
		// Sketch estimation stays off, matching ThemeQueryBenchmark's default, so the numbers are comparable with the
		// recorded theme results and so this harness never writes estimator metadata into the shared store.
		LmdbStoreConfig config = regime.applyTo(ConfigUtil.createConfig().setSketchEstimatorEnabled(false));
		File storeDirectory = themeStoreDirectory();
		verifyThemeStore(storeDirectory, config);
		// No temporary directory: the theme store is shared and clean-protected, so it is never deleted here.
		Fixture fixture = open(Dataset.THEME, regime, config, storeDirectory, null);
		fixture.awaitAdjacency();
		return fixture;
	}

	private static Fixture open(Dataset dataset, ThreeTierRegime regime, LmdbStoreConfig config, File dataDir,
			File temporaryDataDir) {
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		return new Fixture(dataset, regime, repository, store, temporaryDataDir);
	}

	/**
	 * The selective/dense chain shapes of {@link AdjacencyQueryShapeBenchmark}: every subject reaches a middle node,
	 * every middle node fans out to two dense values, and every 64th middle node fans out to 200 selective values. The
	 * asymmetry is what makes a sideways-information-passing mask either pay off or not.
	 */
	private static void populateChainShapes(SailRepositoryConnection connection, int subjects) {
		ValueFactory vf = connection.getValueFactory();
		IRI root = vf.createIRI(FoafData.SHAPE_NAMESPACE, "root");
		IRI selective = vf.createIRI(FoafData.SHAPE_NAMESPACE, "selective");
		IRI selectiveLeaf = vf.createIRI(FoafData.SHAPE_NAMESPACE, "selectiveLeaf");
		IRI dense = vf.createIRI(FoafData.SHAPE_NAMESPACE, "dense");
		IRI denseLeaf = vf.createIRI(FoafData.SHAPE_NAMESPACE, "denseLeaf");
		connection.begin(IsolationLevels.NONE);
		for (int subject = 0; subject < subjects; subject++) {
			IRI subjectIri = vf.createIRI(FoafData.SHAPE_NAMESPACE, "subject/" + subject);
			IRI middle = vf.createIRI(FoafData.SHAPE_NAMESPACE, "middle/" + subject);
			connection.add(subjectIri, root, middle);
			for (int edge = 0; edge < 2; edge++) {
				IRI value = vf.createIRI(FoafData.SHAPE_NAMESPACE, "denseValue/" + subject + "/" + edge);
				connection.add(middle, dense, value);
				connection.add(value, denseLeaf,
						vf.createIRI(FoafData.SHAPE_NAMESPACE, "denseLeaf/" + subject + "/" + edge));
			}
			if ((subject & 63) == 0) {
				for (int edge = 0; edge < 200; edge++) {
					IRI value = vf.createIRI(FoafData.SHAPE_NAMESPACE, "selectiveValue/" + subject + "/" + edge);
					connection.add(middle, selective, value);
					connection.add(value, selectiveLeaf,
							vf.createIRI(FoafData.SHAPE_NAMESPACE, "selectiveLeaf/" + subject + "/" + edge));
				}
			}
		}
		connection.commit();
	}

	/** The correlated-entry shape of {@link CorrelatedBenchmark}: heavy inner fragments plus shared path chains. */
	private static void populateCorrelated(SailRepositoryConnection connection, int outerRows) {
		ValueFactory vf = connection.getValueFactory();
		IRI seedPredicate = vf.createIRI(CorrelatedData.NS, "seed");
		IRI innerPredicate = vf.createIRI(CorrelatedData.NS, "inner");
		IRI payloadPredicate = vf.createIRI(CorrelatedData.NS, "payload");
		IRI pathStartPredicate = vf.createIRI(CorrelatedData.NS, "pathStart");
		IRI nextPredicate = vf.createIRI(CorrelatedData.NS, "next");
		connection.begin(IsolationLevels.NONE);
		for (int outer = 0; outer < outerRows; outer++) {
			IRI outerIri = vf.createIRI(CorrelatedData.NS, "outer/" + outer);
			IRI seed = vf.createIRI(CorrelatedData.NS, "seed/" + outer);
			connection.add(outerIri, seedPredicate, seed);
			for (int inner = 0; inner < CorrelatedData.INNER_FAN_OUT; inner++) {
				IRI leaf = vf.createIRI(CorrelatedData.NS, "leaf/" + outer + "/" + inner);
				connection.add(seed, innerPredicate, leaf);
				connection.add(leaf, payloadPredicate, vf.createLiteral((long) outer * 1_000_003L + inner));
			}
			connection.add(outerIri, pathStartPredicate,
					vf.createIRI(CorrelatedData.NS, "path/" + outer % CorrelatedData.DISTINCT_PATH_STARTS + "/0"));
		}
		for (int start = 0; start < CorrelatedData.DISTINCT_PATH_STARTS; start++) {
			for (int depth = 0; depth < CorrelatedData.PATH_DEPTH; depth++) {
				connection.add(vf.createIRI(CorrelatedData.NS, "path/" + start + "/" + depth), nextPredicate,
						vf.createIRI(CorrelatedData.NS, "path/" + start + "/" + (depth + 1)));
			}
		}
		connection.commit();
	}

	static File themeStoreDirectory() {
		File fromRepositoryRoot = new File(THEME_STORE_PATH);
		if (fromRepositoryRoot.isDirectory()) {
			return fromRepositoryRoot;
		}
		// Running with the module directory as the working directory (IDE, Surefire) instead of the repository root.
		return new File(THEME_STORE_PATH_IN_MODULE);
	}

	/**
	 * Fails unless the shared theme store is present and matches its recorded fingerprint. This harness deliberately
	 * has no rebuild path: the store is several gigabytes, is shared with the theme regression suites, and is protected
	 * from {@code mvn clean} on purpose, so a silent reload would be both slow and destructive.
	 */
	private static void verifyThemeStore(File storeDirectory, LmdbStoreConfig config) {
		File fingerprint = new File(storeDirectory, THEME_EXPECTED_SIZES_FILE);
		if (!fingerprint.isFile()) {
			throw new IllegalStateException("The shared theme store is missing at " + storeDirectory.getAbsolutePath()
					+ ". Load it once by running ThemeQueryBenchmark, then re-run this harness; the three-tier"
					+ " harness never rebuilds it.");
		}
		Properties properties = new Properties();
		try (FileInputStream input = new FileInputStream(fingerprint)) {
			properties.load(input);
		} catch (IOException e) {
			throw new UncheckedIOException(e);
		}
		String recordedIndexes = properties.getProperty(THEME_TRIPLE_INDEXES_PROPERTY);
		if (!config.getTripleIndexes().equals(recordedIndexes)) {
			throw new IllegalStateException("The shared theme store was loaded with triple indexes " + recordedIndexes
					+ " but this harness requests " + config.getTripleIndexes()
					+ "; refusing to open it because a mismatch would trigger a multi-gigabyte reload.");
		}
		expectSize(properties, storeDirectory, THEME_TRIPLES_SIZE_PROPERTY, THEME_TRIPLES_DATA_FILE);
		expectSize(properties, storeDirectory, THEME_VALUES_SIZE_PROPERTY, THEME_VALUES_DATA_FILE);
	}

	private static void expectSize(Properties properties, File storeDirectory, String property, String relativePath) {
		String recorded = properties.getProperty(property);
		long actual = new File(storeDirectory, relativePath).length();
		if (recorded == null || Long.parseLong(recorded) != actual) {
			throw new IllegalStateException("The shared theme store looks incomplete: " + relativePath + " is "
					+ actual + " bytes but " + property + " records " + recorded
					+ ". Re-run ThemeQueryBenchmark to reload it.");
		}
	}

	private static File temporaryDirectory(String prefix) {
		try {
			return Files.createTempDirectory(prefix).toFile();
		} catch (IOException e) {
			throw new UncheckedIOException(e);
		}
	}

	/** One opened store plus the operations the harness performs against it. */
	static final class Fixture {

		private final Dataset dataset;
		private final ThreeTierRegime regime;
		private final SailRepository repository;
		private final LmdbStore store;
		private final File temporaryDataDir;
		private final Set<ThreeTierParityCorpus> prepared = EnumSet.noneOf(ThreeTierParityCorpus.class);
		private long reportedPlanes;
		private long reportedViews;
		private long reportedKernels;

		private Fixture(Dataset dataset, ThreeTierRegime regime, SailRepository repository, LmdbStore store,
				File temporaryDataDir) {
			this.dataset = dataset;
			this.regime = regime;
			this.repository = repository;
			this.store = store;
			this.temporaryDataDir = temporaryDataDir;
		}

		LmdbStore store() {
			return store;
		}

		/** Evaluates one corpus query and returns its row count. */
		long execute(ThreeTierParityCorpus entry) {
			try (SailRepositoryConnection connection = repository.getConnection();
					TupleQueryResult result = connection.prepareTupleQuery(entry.query()).evaluate()) {
				long rows = 0L;
				while (result.hasNext()) {
					result.next();
					rows++;
				}
				return rows;
			}
		}

		/**
		 * Prepares one cell for measurement and returns its row count. In the Janino regime this runs the query once
		 * (which, with the admission threshold lowered to zero, schedules kernel compilation), blocks until every
		 * scheduled compilation finishes, then runs it again, so the measured iterations execute compiled code instead
		 * of racing the compiler thread. In the other two regimes it is a single warm-up execution.
		 *
		 * <p>
		 * Idempotent per cell, because the fixture is shared by every benchmark method that uses the same dataset.
		 */
		synchronized long prepare(ThreeTierParityCorpus entry) {
			if (!prepared.add(entry)) {
				return execute(entry);
			}
			long rows = execute(entry);
			if (!regime.janinoEnabled()) {
				return rows;
			}
			long timeout = Long.getLong(COMPILE_TIMEOUT_SECONDS_PROPERTY, DEFAULT_COMPILE_TIMEOUT_SECONDS);
			try {
				if (!JaninoPipelineTestAccess.awaitCompilations(timeout, TimeUnit.SECONDS)) {
					throw new IllegalStateException("Janino compilation for " + entry.benchmarkMethodName()
							+ " did not finish within " + timeout + " seconds");
				}
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new IllegalStateException("Interrupted while awaiting Janino compilation", e);
			}
			return execute(entry);
		}

		/**
		 * One line describing which tier did the work since the previous call: the engagement witness that turns a JMH
		 * score into evidence about <em>which</em> tier produced it. Reported per measured iteration, because JMH stops
		 * forwarding a forked JVM's output before trial teardown runs, so a once-per-trial summary never reaches the
		 * result file.
		 */
		synchronized String engagementSinceLastReport() {
			long planes = AdjacencyEngagementTestAccess.lookupHits(store)
					+ AdjacencyEngagementTestAccess.exactMisses(store)
					+ AdjacencyEngagementTestAccess.plannerStatsHits(store);
			long views = AdjacencyEngagementTestAccess.kernelViewsServed();
			long kernels = JaninoPipelineTestAccess.openedAny() + JoinDispatchTestAccess.janinoAggregateOpened();
			String line = "regime=" + regime.paramValue()
					+ " adjacencyState=" + AdjacencyEngagementTestAccess.state(store)
					+ " planes=" + (planes - reportedPlanes)
					+ " kernelViews=" + (views - reportedViews)
					+ " kernelOpens=" + (kernels - reportedKernels)
					+ " janinoCache=" + JaninoPipelineTestAccess.cacheSummary()
					+ " fallbacks=" + AdjacencyEngagementTestAccess.fallbackSummary(store);
			reportedPlanes = planes;
			reportedViews = views;
			reportedKernels = kernels;
			return line;
		}

		void close() {
			try {
				repository.shutDown();
			} finally {
				if (temporaryDataDir != null && temporaryDataDir.exists()) {
					try {
						FileUtils.deleteDirectory(temporaryDataDir);
					} catch (IOException e) {
						throw new UncheckedIOException(e);
					}
				}
			}
		}

		private void awaitAdjacency() {
			if (regime.adjacencyMode() != DirectAdjacencyMode.PREFER) {
				return;
			}
			if (dataset != Dataset.THEME) {
				// Small generated stores build synchronously, which removes the background-scheduling variable.
				AdjacencyEngagementTestAccess.buildNow(store);
			}
			long timeout = Long.getLong(ADJACENCY_TIMEOUT_SECONDS_PROPERTY, DEFAULT_ADJACENCY_TIMEOUT_SECONDS);
			try {
				if (!store.awaitDirectAdjacencyReady(timeout, TimeUnit.SECONDS)) {
					throw new IllegalStateException("Direct adjacency did not become exact for the " + dataset
							+ " dataset within " + timeout + " seconds: "
							+ store.getDirectAdjacencyReadinessDescription());
				}
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new IllegalStateException("Interrupted while waiting for direct adjacency", e);
			}
		}
	}
}
